import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";

const styles = stylex.create({
  chip: { color: colors.blueLink, fontWeight: 600, backgroundColor: colors.infoAlpha10, borderRadius: 4, paddingInline: 2 },
});

export default function MentionChip({ name, url }) {
  return (
    <span data-href={url} {...stylex.props(styles.chip)}>
      {name}
    </span>
  );
}
