import * as stylex from "@stylexjs/stylex";
import UIIconButton from "UIIconButton.react";
import UITooltip from "UITooltip.react";
import { UIRow } from "UIStack.react";

const BUTTONS = [
  ["avatar", "smile", "Comment with an avatar sticker"],
  ["emoji", "smile", "Insert an emoji"],
  ["media_upload", "camera", "Attach a photo or video"],
  ["gif", "gif", "Comment with a GIF"],
  ["sticker", "sticker", "Comment with a sticker"],
];

const styles = stylex.create({ bar: { justifyContent: "flex-end", gap: 2, paddingTop: 2 } });

export default function ComposerToolbar({ enabled }) {
  return (
    <UIRow xstyle={styles.bar}>
      {BUTTONS.filter(([key]) => enabled.has(key)).map(([key, icon, label]) => (
        <UITooltip key={key} text={label}>
          <UIIconButton icon={icon} label={label} size={28} iconSize={16} filled={false} />
        </UITooltip>
      ))}
    </UIRow>
  );
}
