// The comment composer: a Lexical plain-text editor whose plugins the server
// configures (mentions, hashtags, emoticons, link detection, ...), with the
// viewer's avatar and the attachment buttons. Nothing is ever submitted.
import { useMemo } from "react";
import { LexicalComposer } from "@lexical/react/LexicalComposer";
import { PlainTextPlugin } from "@lexical/react/LexicalPlainTextPlugin";
import { ContentEditable } from "@lexical/react/LexicalContentEditable";
import { HistoryPlugin } from "@lexical/react/LexicalHistoryPlugin";
import { HashtagPlugin } from "@lexical/react/LexicalHashtagPlugin";
import { AutoLinkPlugin } from "@lexical/react/LexicalAutoLinkPlugin";
import { ClearEditorPlugin } from "@lexical/react/LexicalClearEditorPlugin";
import { OnChangePlugin } from "@lexical/react/LexicalOnChangePlugin";
import { LexicalErrorBoundary } from "@lexical/react/LexicalErrorBoundary";
import { HashtagNode } from "@lexical/hashtag";
import { AutoLinkNode, LinkNode } from "@lexical/link";
import * as stylex from "@stylexjs/stylex";
import { colors, radii, type } from "BaseTokens.stylex";
import { commentComposerTokens } from "ComponentTokens.stylex";
import UIAvatar from "UIAvatar.react";
import UIText from "UIText.react";
import { UIRow } from "UIStack.react";
import { MentionNode } from "MentionNode";
import MentionsPlugin from "MentionsPlugin.react";
import EmoticonPlugin from "EmoticonPlugin.react";
import ComposerToolbar from "ComposerToolbar.react";
import ComposerCharacterCount from "ComposerCharacterCount.react";
import ErrorPubSub from "ErrorPubSub";
import EventLogger from "EventLogger";

const URL_MATCHER = /((https?:\/\/(www\.)?)|(www\.))[-a-zA-Z0-9@:%._+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_+.~#?&//=]*)/;
const MATCHERS = [
  (text) => {
    const match = URL_MATCHER.exec(text);
    return match ? { index: match.index, length: match[0].length, text: match[0], url: match[0].startsWith("http") ? match[0] : `https://${match[0]}` } : null;
  },
];

const styles = stylex.create({
  row: { alignItems: "flex-start", gap: 8, paddingBlock: 8, paddingInline: 16 },
  field: { position: "relative", flexGrow: 1, minWidth: 0, borderRadius: radii.xxl, backgroundColor: colors.inputBackground, paddingTop: 8, paddingInline: 12, paddingBottom: 4 },
  editable: { outline: "none", minHeight: 20, maxHeight: 180, overflowY: "auto", fontSize: type.bodySize, lineHeight: type.bodyLineHeight, color: colors.primaryText, whiteSpace: "pre-wrap", overflowWrap: "anywhere" },
  placeholder: { position: "absolute", top: 8, left: 12, pointerEvents: "none", userSelect: "none" },
  hashtag: { color: colors.blueLink, fontWeight: commentComposerTokens.fontWeight },
  link: { color: colors.blueLink, textDecoration: "underline" },
  paragraph: { margin: 0 },
});

const THEME = {
  hashtag: stylex.props(styles.hashtag).className,
  link: stylex.props(styles.link).className,
  paragraph: stylex.props(styles.paragraph).className,
};

function onError(error) {
  ErrorPubSub.reportError(error, { name: "lexical" });
}

export default function CommentComposer({ placeholder, plugins, maxLength, viewerAvatar, composerId }) {
  const enabled = useMemo(() => new Set(plugins.filter((plugin) => plugin.enabled).map((plugin) => plugin.key)), [plugins]);
  const pluginConfigs = useMemo(() => plugins.map((plugin) => JSON.parse(plugin.config)), [plugins]);
  const initialConfig = useMemo(
    () => ({
      namespace: `comment-composer-${composerId}`,
      nodes: [HashtagNode, MentionNode, AutoLinkNode, LinkNode],
      theme: THEME,
      onError,
    }),
    [composerId],
  );
  return (
    <LexicalComposer initialConfig={initialConfig}>
      <UIRow xstyle={styles.row}>
        <UIAvatar src={viewerAvatar} size={32} />
        <div {...stylex.props(styles.field)} data-testid="comment-composer">
          <PlainTextPlugin
            contentEditable={<ContentEditable aria-label={placeholder} aria-placeholder={placeholder} data-testid="comment-composer-input" placeholder={<UIText color="secondary" xstyle={styles.placeholder}>{placeholder}</UIText>} {...stylex.props(styles.editable)} />}
            ErrorBoundary={LexicalErrorBoundary}
          />
          <HistoryPlugin />
          <ClearEditorPlugin />
          {enabled.has("mentions") ? <MentionsPlugin /> : null}
          {enabled.has("hashtags") ? <HashtagPlugin /> : null}
          {enabled.has("emoticons") ? <EmoticonPlugin /> : null}
          {enabled.has("link_preview") ? <AutoLinkPlugin matchers={MATCHERS} /> : null}
          <OnChangePlugin ignoreSelectionChange onChange={(editorState) => EventLogger.log("composer", { id: composerId, size: editorState._nodeMap.size, plugins: pluginConfigs.length })} />
          <ComposerCharacterCount maxLength={maxLength} />
          <ComposerToolbar enabled={enabled} />
        </div>
      </UIRow>
    </LexicalComposer>
  );
}
