// Replaces typed emoticons with emoji as you type, as the reference's
// comment composer does.
import { useEffect } from "react";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { TextNode } from "lexical";

const EMOTICONS = { ":)": "\u{1F642}", ":(": "\u{1F641}", ":D": "\u{1F600}", ";)": "\u{1F609}", "<3": "❤️", ":P": "\u{1F61B}", ":o": "\u{1F62E}" };
const PATTERN = /(:\)|:\(|:D|;\)|<3|:P|:o)$/;

export default function EmoticonPlugin() {
  const [editor] = useLexicalComposerContext();
  useEffect(
    () =>
      editor.registerNodeTransform(TextNode, (node) => {
        if (!node.isSimpleText()) {
          return;
        }
        const text = node.getTextContent();
        const match = text.match(PATTERN);
        if (!match) {
          return;
        }
        const offset = text.length - match[0].length;
        const target = offset === 0 ? node : node.splitText(offset)[1];
        target.setTextContent(EMOTICONS[match[0]]);
        target.select();
      }),
    [editor],
  );
  return null;
}
