// "@" opens a typeahead of people. Each change of the query after the "@"
// requests matches from the server; choosing one replaces the query with a
// mention node.
import { useCallback, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import { fetchQuery, graphql } from "react-relay";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { LexicalTypeaheadMenuPlugin, MenuOption, useBasicTypeaheadTriggerMatch } from "@lexical/react/LexicalTypeaheadMenuPlugin";
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import { typeaheadItemTokens } from "ComponentTokens.stylex";
import RelayEnvironment from "RelayEnvironment";
import UIAvatar from "UIAvatar.react";
import UIText from "UIText.react";
import { $createMentionNode } from "MentionNode";
import { emitStepEvent, track } from "Workload";

const MentionsQuery = graphql`
  query MentionsPluginQuery($query: String!) {
    mention_typeahead(query: $query, first: 6) {
      id
      name
      url
      profile_picture(size: 32) {
        uri
      }
    }
  }
`;

const styles = stylex.create({
  menu: { position: "absolute", bottom: 28, left: 0, width: 280, padding: 6, listStyle: "none", margin: 0, borderRadius: radii.lg, backgroundColor: colors.popoverBackground, boxShadow: elevation.e4, zIndex: 70 },
  option: { display: "flex", alignItems: "center", gap: 8, padding: 6, borderRadius: typeaheadItemTokens.radius, cursor: "pointer" },
  selected: { backgroundColor: colors.hoverOverlay },
});

class MentionOption extends MenuOption {
  constructor(person) {
    super(person.id);
    this.person = person;
  }
}

function MentionMenu({ options, selectedIndex, selectOptionAndCleanUp, setHighlightedIndex }) {
  return (
    <ul role="listbox" aria-label="People to mention" data-testid="mentions-menu" {...stylex.props(styles.menu)}>
      {options.map((option, i) => (
        <li
          key={option.key}
          ref={option.setRefElement}
          role="option"
          aria-selected={selectedIndex === i}
          onMouseEnter={() => setHighlightedIndex(i)}
          onClick={() => selectOptionAndCleanUp(option)}
          {...stylex.props(styles.option, selectedIndex === i && styles.selected)}
        >
          <UIAvatar src={option.person.profile_picture?.uri} size={28} />
          <UIText type="meta" weight="semibold">
            {option.person.name}
          </UIText>
        </li>
      ))}
    </ul>
  );
}

export default function MentionsPlugin() {
  const [editor] = useLexicalComposerContext();
  const [query, setQuery] = useState(null);
  const [people, setPeople] = useState([]);
  const triggerFn = useBasicTypeaheadTriggerMatch("@", { minLength: 0, maxLength: 30 });

  const onQueryChange = useCallback((value) => {
    setQuery(value);
    if (value === null) {
      setPeople([]);
      return;
    }
    track(
      fetchQuery(RelayEnvironment, MentionsQuery, { query: value })
        .toPromise()
        .then((data) => {
          setPeople(data?.mention_typeahead ?? []);
          emitStepEvent("mentions-results", { query: value });
        }),
    );
  }, []);

  const options = useMemo(() => people.map((person) => new MentionOption(person)), [people]);

  const onSelectOption = useCallback(
    (option, nodeToReplace, closeMenu) => {
      editor.update(() => {
        const mention = $createMentionNode(option.person.id, option.person.name, option.person.url);
        if (nodeToReplace) {
          nodeToReplace.replace(mention);
        }
        mention.selectNext();
        closeMenu();
      });
    },
    [editor],
  );

  return (
    <LexicalTypeaheadMenuPlugin
      onQueryChange={onQueryChange}
      onSelectOption={onSelectOption}
      triggerFn={triggerFn}
      options={query === null ? [] : options}
      menuRenderFn={(anchorElementRef, props) => (anchorElementRef.current && props.options.length ? createPortal(<MentionMenu {...props} />, anchorElementRef.current) : null)}
    />
  );
}
