// A mention in a comment: an inline decorator node that React renders as a
// link to the person.
import { DecoratorNode } from "lexical";
import MentionChip from "MentionChip.react";

export class MentionNode extends DecoratorNode {
  static getType() {
    return "mention";
  }

  static clone(node) {
    return new MentionNode(node.__personId, node.__name, node.__url, node.__key);
  }

  static importJSON(json) {
    return new MentionNode(json.personId, json.name, json.url);
  }

  constructor(personId, name, url, key) {
    super(key);
    this.__personId = personId;
    this.__name = name;
    this.__url = url;
  }

  exportJSON() {
    return { type: "mention", version: 1, personId: this.__personId, name: this.__name, url: this.__url };
  }

  createDOM() {
    const span = document.createElement("span");
    span.setAttribute("data-mention", this.__personId);
    return span;
  }

  updateDOM() {
    return false;
  }

  isInline() {
    return true;
  }

  getTextContent() {
    return this.__name;
  }

  decorate() {
    return <MentionChip name={this.__name} url={this.__url} />;
  }
}

export function $createMentionNode(personId, name, url) {
  return new MentionNode(personId, name, url);
}
