// Counts the editor's characters on every update and warns near the limit.
import { useEffect, useState } from "react";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $getRoot } from "lexical";
import UIText from "UIText.react";

export default function ComposerCharacterCount({ maxLength }) {
  const [editor] = useLexicalComposerContext();
  const [length, setLength] = useState(0);
  useEffect(
    () =>
      editor.registerUpdateListener(({ editorState }) => {
        editorState.read(() => setLength($getRoot().getTextContentSize()));
      }),
    [editor],
  );
  if (length < maxLength * 0.9) {
    return null;
  }
  return (
    <UIText type="caption" color="secondary">
      {maxLength - length}
    </UIText>
  );
}
