// The dialog's comment composer, configured by the server's composer
// settings for the post.
import { graphql, useFragment, useLazyLoadQuery } from "react-relay";
import CommentComposer from "CommentComposer.react";

export default function PostDialogComposer({ feedback }) {
  const data = useFragment(
    graphql`
      fragment PostDialogComposer_feedback on Feedback {
        id
        composer_config {
          placeholder
          max_length
          plugins {
            key
            enabled
            config
          }
        }
      }
    `,
    feedback,
  );
  const viewer = useLazyLoadQuery(
    graphql`
      query PostDialogComposerViewerQuery {
        viewer {
          actor {
            profile_picture(size: 40) {
              uri
            }
          }
        }
      }
    `,
    {},
    { fetchPolicy: "store-only" },
  );
  if (!data?.composer_config) {
    return null;
  }
  const config = data.composer_config;
  return <CommentComposer composerId={data.id} placeholder={config.placeholder} plugins={config.plugins} maxLength={config.max_length} viewerAvatar={viewer.viewer?.actor?.profile_picture?.uri} />;
}
