// The post dialog, opened over the feed from a story's "Comment" button: the
// post itself, its comments with their order and pagination, and the comment
// composer. The comments and the composer's configuration arrive in deferred
// payloads after the post.
import { Suspense, useContext, useEffect } from "react";
import { graphql, useLazyLoadQuery } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { dialogHeaderTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import UIDialog from "UIDialog.react";
import UIText from "UIText.react";
import UIIconButton from "UIIconButton.react";
import UIDivider from "UIDivider.react";
import UIErrorBoundary from "UIErrorBoundary.react";
import { UIRow } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import { RouterContext } from "RouterContext";
import FeedStory from "FeedStory.react";
import PostDialogComments from "PostDialogComments.react";
import PostDialogComposer from "PostDialogComposer.react";
import PostDialogGlimmer from "PostDialogGlimmer.react";
import { emitStepEvent } from "Workload";

const styles = stylex.create({
  header: { position: "relative", justifyContent: "center", minHeight: 60, borderBottom: `1px solid ${colors.divider}`, flexShrink: 0, paddingInline: dialogHeaderTokens.paddingX },
  close: { position: "absolute", right: 16, top: 12 },
  body: { overflowY: "auto", flexGrow: 1, minHeight: 0, overscrollBehavior: "contain" },
  footer: { flexShrink: 0, borderTop: `1px solid ${colors.divider}` },
});

function PostDialogContent({ storyId, onClose }) {
  const data = useLazyLoadQuery(
    graphql`
      query PostDialogQuery($storyID: ID!) {
        node(id: $storyID) {
          ... on Story {
            id
            actors {
              name
            }
            ...FeedStory_story @alias(as: "post")
            feedback {
              ...PostDialogComments_feedback @defer(label: "PostDialog_comments")
              ...PostDialogComposer_feedback @defer(label: "PostDialog_composer")
            }
          }
        }
      }
    `,
    { storyID: storyId },
    { fetchPolicy: "network-only" },
  );
  const story = data.node;
  const name = story?.actors?.[0]?.name ?? "";
  return (
    <>
      <UIRow xstyle={styles.header}>
        <UIText as="h2" type="headline3">
          {fbt(fbt.param("name", name) + "'s post", "post dialog title")}
        </UIText>
        <UIIconButton icon="close" label="Close" onPress={onClose} xstyle={styles.close} testid="post-dialog-close" />
      </UIRow>
      <div {...stylex.props(styles.body)} data-testid="post-dialog-body">
        {story?.post ? <FeedStory story={story.post} position={0} mode="dialog" /> : null}
        <UIDivider inset />
        <Suspense fallback={<PostDialogGlimmer />}>{story?.feedback ? <PostDialogComments feedback={story.feedback} /> : null}</Suspense>
      </div>
      <div {...stylex.props(styles.footer)}>
        <Suspense fallback={null}>{story?.feedback ? <PostDialogComposer feedback={story.feedback} /> : null}</Suspense>
      </div>
    </>
  );
}

export default function PostDialog({ storyId }) {
  const router = useContext(RouterContext);
  const close = () => router?.closeDialog();
  useEffect(() => () => emitStepEvent("dialog-closed"), []);
  return (
    <UIDialog label="Post" onClose={close} width={700} testid="post-dialog">
      <LoggingSurface name="post_dialog">
        <UIErrorBoundary name="post_dialog_content">
          <Suspense fallback={<PostDialogGlimmer />}>
            <PostDialogContent storyId={storyId} onClose={close} />
          </Suspense>
        </UIErrorBoundary>
      </LoggingSurface>
    </UIDialog>
  );
}
